# Verify the requantize implementation and the max-then-requantize optimization.
import random
from fractions import Fraction

def req_mine(z, sh):
    if sh:
        half = 1 << (sh-1)
        if z >= 0:
            z = (z + half) >> sh
        else:
            z = -(((-z) + half) >> sh)
    if z < 0: z = 0
    elif z > 127: z = 127
    return z

def req_ref(z, sh):
    # round half away from zero of z / 2**sh, then clamp
    q = Fraction(z, 2**sh) if sh else Fraction(z)
    if q >= 0:
        import math
        r = math.floor(q + Fraction(1,2))
    else:
        import math
        r = -math.floor(-q + Fraction(1,2))
    return max(0, min(127, r))

rnd = random.Random(0)
bad = 0
for sh in range(0,17):
    zs = list(range(-300, 300))
    # critical tie points
    for m in range(-6, 7):
        base = m * (1 << sh)
        for d in range(-4, 5):
            zs.append(base + d)
        if sh: 
            for d in range(-4,5):
                zs.append(base + (1 << (sh-1)) + d)
    zs += [rnd.randint(-2**32, 2**32) for _ in range(20000)]
    zs += [-2**31-1000000, 2**31+1000000, 0]
    for z in zs:
        a = req_mine(z, sh); b = req_ref(z, sh)
        if a != b:
            bad += 1
            if bad < 5: print("MISMATCH", z, sh, a, b)
print("requant mismatches:", bad)

# monotonicity => max-then-requantize equals requantize-each-then-max
bad2 = 0
for sh in range(0,17):
    for _ in range(20000):
        n = rnd.randint(1,12)
        zs = [rnd.randint(-2**33, 2**33) for _ in range(n)]
        a = req_mine(max(zs), sh)
        b = max(req_mine(z, sh) for z in zs)
        if a != b:
            bad2 += 1
            if bad2<5: print("MONO MISMATCH", sh, zs)
print("monotonicity mismatches:", bad2)
PYEOF
